def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # The full 2-colored divider is the axis toward which the object moves.
    line = next((r for r, row in enumerate(g) if all(v == 2 for v in row)), None)
    if line is not None:
        obj = [(r, c, g[r][c]) for r in range(h) for c in range(w) if g[r][c] not in (2, 4)]
        if not obj:
            return g
        top, bottom = min(r for r, c, v in obj), max(r for r, c, v in obj)
        shift = line - 1 - bottom if bottom < line else line + 1 - top
        for r, c, v in obj:
            g[r][c] = 4
        for r, c, v in obj:
            g[r + shift][c] = v
        # Paint an 8-colored row just beyond the moved object, away from the divider.
        edge = max(r + shift for r, c, v in obj) + 1 if top > line else min(r + shift for r, c, v in obj) - 1
        for c in range(w):
            g[edge][c] = 8
        return g
    col = next((c for c in range(w) if all(g[r][c] == 2 for r in range(h))), None)
    if col is not None:
        obj = [(r, c, g[r][c]) for r in range(h) for c in range(w) if g[r][c] not in (2, 4)]
        if not obj:
            return g
        left, right = min(c for r, c, v in obj), max(c for r, c, v in obj)
        shift = col - 1 - right if right < col else col + 1 - left
        for r, c, v in obj:
            g[r][c] = 4
        for r, c, v in obj:
            g[r][c + shift] = v
        edge = max(c + shift for r, c, v in obj) + 1 if left > col else min(c + shift for r, c, v in obj) - 1
        for r in range(h):
            g[r][edge] = 8
    return g
